// Pseudo-code: chunk transcript, call SageMaker per chapter, write outputs
async function processChapteredTranscript(transcript) {
  const chapters = chunkByTime(transcript);
  for (const c of chapters) {
    const summary = await sageMaker.summarize(c.text);
    await s3.put(`episode/${transcript.episodeId}/${c.start}-${c.end}.txt`, c.text);
    await s3.put(`episode/${transcript.episodeId}/${c.start}-${c.end}.summary.txt`, summary);
  }
}
